// Atlas loading and sprite drawing.
// Atlases are generated by `npm run art` into /atlases (see tools/art).
import { ZOOM } from '../config.js';

const ATLAS_SCALE = 2; // atlases are authored at 2x logical pixels

export class Atlas {
    constructor(image, meta) {
        this.image = image;
        this.frames = meta.frames;
    }

    has(name) {
        return !!this.frames[name];
    }

    // Draw frame with its top-left at CSS-pixel position (dx, dy).
    // Frames are authored at 2x and ZOOM is 2, so default dest size = frame size.
    draw(ctx, name, dx, dy) {
        const f = this.frames[name];
        if (!f) return;
        const scale = ZOOM / ATLAS_SCALE;
        ctx.drawImage(this.image, f.x, f.y, f.w, f.h,
            Math.round(dx), Math.round(dy), f.w * scale, f.h * scale);
    }

    // Drawn centered horizontally on a tile, bottom-aligned (for tall sprites)
    drawAnchored(ctx, name, dx, dy, tilePx) {
        const f = this.frames[name];
        if (!f) return;
        const scale = ZOOM / ATLAS_SCALE;
        const w = f.w * scale, h = f.h * scale;
        ctx.drawImage(this.image, f.x, f.y, f.w, f.h,
            Math.round(dx + (tilePx - w) / 2), Math.round(dy + tilePx - h), w, h);
    }

    frameSize(name) {
        const f = this.frames[name];
        const scale = ZOOM / ATLAS_SCALE;
        return f ? { w: f.w * scale, h: f.h * scale } : { w: 0, h: 0 };
    }
}

async function loadOne(name) {
    const [meta, image] = await Promise.all([
        fetch(`/atlases/${name}.json`).then(r => {
            if (!r.ok) throw new Error(`atlas ${name} metadata missing`);
            return r.json();
        }),
        new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => reject(new Error(`atlas ${name} image missing`));
            img.src = `/atlases/${name}.png`;
        })
    ]);
    return new Atlas(image, meta);
}

export class Assets {
    constructor() {
        this.atlases = new Map();
    }

    async load(name) {
        if (!this.atlases.has(name)) {
            this.atlases.set(name, await loadOne(name));
        }
        return this.atlases.get(name);
    }

    get core() { return this.atlases.get('core'); }

    async loadBiome(biomeId) {
        return this.load(`biome-${biomeId}`);
    }

    biome(biomeId) {
        return this.atlases.get(`biome-${biomeId}`);
    }
}
